using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using NPOI.HWPF.Extractor;
namespace Ansary;
public sealed record PlainHeading(int Index,int Level,string Text);
public static class TextFormats {
 public static bool Supported(string path)=>Path.GetExtension(path).ToLowerInvariant() is ".docx" or ".doc" or ".txt" or ".md" or ".markdown";
 public static bool Markdown(string path)=>Path.GetExtension(path).ToLowerInvariant() is ".md" or ".markdown";
 public static string[] Read(string path){
  string ext=Path.GetExtension(path).ToLowerInvariant();
  if(ext is not (".doc" or ".txt" or ".md" or ".markdown"))throw new InvalidDataException("صيغة المستند غير مدعومة");
  if(new FileInfo(path).Length>64L*1024*1024)throw new InvalidDataException("الملف يتجاوز حد القراءة النصية: 64 MB");
  if(ext==".doc")return ReadDoc(path);
  byte[] bytes=File.ReadAllBytes(path);string text;
  if(bytes.Length>=2&&((bytes[0]==255&&bytes[1]==254)||(bytes[0]==254&&bytes[1]==255))){using var reader=new StreamReader(new MemoryStream(bytes),Encoding.UTF8,true);text=reader.ReadToEnd();}
  else if(bytes.Length>=4&&(bytes[0]==0||bytes[1]==0)){int even=0,odd=0,n=Math.Min(bytes.Length,4096);for(int i=0;i<n;i++){if(bytes[i]==0){if(i%2==0)even++;else odd++;}}if(Math.Max(even,odd)>n/8)text=(odd>=even?new UnicodeEncoding(false,false,true):new UnicodeEncoding(true,false,true)).GetString(bytes);else text=Decode(bytes);}
  else text=Decode(bytes);
  if(text.Length>32*1024*1024)throw new InvalidDataException("النص أكبر من حد العرض الآمن");
  text=text.TrimStart('\uFEFF');return text.Length==0?Array.Empty<string>():text.Replace("\r\n","\n").Replace('\r','\n').Split('\n');
 }
 static string Decode(byte[] bytes){try{return new UTF8Encoding(false,true).GetString(bytes);}catch(DecoderFallbackException){Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);int code=System.Globalization.CultureInfo.CurrentCulture.TextInfo.ANSICodePage;return Encoding.GetEncoding(code==65001?1256:code,EncoderFallback.ExceptionFallback,DecoderFallback.ExceptionFallback).GetString(bytes);}}
 static string[] ReadDoc(string path){Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);using var input=File.OpenRead(path);var signature=new byte[8];if(input.Read(signature,0,8)!=8||!signature.SequenceEqual(new byte[]{0xd0,0xcf,0x11,0xe0,0xa1,0xb1,0x1a,0xe1}))throw new InvalidDataException("ليس ملف Word DOC ثنائيًا صالحًا؛ تغيير الامتداد وحده لا يحوّل المستند");input.Position=0;try{var extractor=new WordExtractor(input);long count=0;var result=new List<string>();foreach(string paragraph in extractor.ParagraphText){string text=WordExtractor.StripFields(paragraph).TrimEnd('\r','\n').Replace('\a','\t');text=new string(text.Where(c=>!char.IsControl(c)||c is '\t' or '\n').ToArray());count+=text.Length;if(count>32L*1024*1024)throw new InvalidDataException("نص DOC أكبر من حد العرض الآمن");result.Add(text);}return result.ToArray();}catch(Exception e) when(e is not OutOfMemoryException){throw new InvalidDataException("تعذرت قراءة DOC: "+e.Message,e);}}
 public static List<PlainHeading> Headings(string path){var lines=Read(path);var result=new List<PlainHeading>();char fence='\0';int fenceLength=0;for(int i=0;i<lines.Length;i++){var block=Regex.Match(lines[i],"^ {0,3}(`{3,}|~{3,})(.*)$");if(block.Success){char ch=block.Groups[1].Value[0];int length=block.Groups[1].Length;if(fence=='\0'){fence=ch;fenceLength=length;}else if(ch==fence&&length>=fenceLength&&string.IsNullOrWhiteSpace(block.Groups[2].Value))fence='\0';continue;}if(fence!='\0')continue;var atx=Regex.Match(lines[i],"^ {0,3}(#{1,6})(?:[ \t]+|$)(.*)$");if(atx.Success){string text=Regex.Replace(atx.Groups[2].Value,"[ \t]+#+[ \t]*$","").Trim();if(text.Length>0)result.Add(new PlainHeading(i,atx.Groups[1].Length-1,text));continue;}if(i+1<lines.Length&&!string.IsNullOrWhiteSpace(lines[i])&&!lines[i].StartsWith("    ")&&!lines[i].StartsWith("\t")){var underline=Regex.Match(lines[i+1],"^ {0,3}(=+|-+)[ \t]*$");if(underline.Success){result.Add(new PlainHeading(i,underline.Groups[1].Value[0]=='='?0:1,lines[i].Trim()));i++;}}}return result;}
 public static void Verify(){DocReaderRegression.Verify();string dir=Path.Combine(Path.GetTempPath(),"AnsaryFormats-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string content="# عنوان عربي\nنص قابل للبحث\n## قسم ثان\n```\n# ليس عنوانا\n```\nقسم ثالث\n---\n";string[] names={"arabic.md","copy.markdown","unicode.MD","plain.txt"};for(int i=0;i<names.Length;i++){string path=Path.Combine(dir,names[i]);File.WriteAllText(path,content,i==2?Encoding.Unicode:new UTF8Encoding(false));if(Core.Read(path)[1]!="نص قابل للبحث"||!Core.Match(Core.Read(path)[1],Core.Terms("نص قابل")))throw new InvalidDataException("Arabic Markdown reading/search regression");}if(Headings(Path.Combine(dir,names[0])).Count!=3||Core.Scan(dir,CancellationToken.None).Files.Count!=4)throw new InvalidDataException("Markdown discovery/outline regression");string? fixture=Environment.GetEnvironmentVariable("ANSARY_DOC_FIXTURE");if(!string.IsNullOrEmpty(fixture)){string target=Path.Combine(dir,"legacy.DOC");File.Copy(fixture,target);var paragraphs=Core.Read(target);if(paragraphs.Length!=14||paragraphs[0]!="This is a simple word document")throw new InvalidDataException("DOC fixture regression");}}finally{Directory.Delete(dir,true);}}
}
